counts = {}
for value in ["B", "A", "B", "C", "A", "B"]:
    counts[value] = counts.get(value, 0) + 1
for value in counts:
    print(value, counts[value])

def frequencies(values):
    result = {}
    for value in values:
        result[value] = result.get(value, 0) + 1
    return result

print(frequencies([]))
print(frequencies(["A", "A"]))
print(frequencies(["B", "A", "B", "C"]))

def folded_frequencies(words):
    result = {}
    for word in words:
        key = word.lower()
        result[key] = result.get(key, 0) + 1
    return result

print(folded_frequencies([]))
print(folded_frequencies(["Cat", "cat", "DOG"]))
print(folded_frequencies(["A", "a", "A", "b"]))
